    code, name, description, area = IMPORT_PERMISSION
    Permission.objects.update_or_create(code=code, defaults={"name": name, "description": description, "area": area})

    def system_role(code, name, description, is_company_role, perms):
        role = Role.objects.filter(code=code).first() or Role(code=code)
        role.name, role.description = name, description
        role.is_company_role, role.is_system, role.company = is_company_role, True, None
        role.save()
        role.permissions.set(Permission.objects.filter(code__in=perms))
        return role

    system_role("COMPANY_BOSS", "Company boss", "Runs a service provider: every company page, services, prices, staff and payments", True, BOSS_PERMISSIONS)
    # A role the admin made called "Receptionist" would clash with the name
    Role.objects.filter(name__iexact="Receptionist").exclude(code="COMPANY_RECEPTIONIST").update(name="Receptionist (old)")
    receptionist = system_role("COMPANY_RECEPTIONIST", "Receptionist", "Records the services EUCL employees use and takes attendance", True, RECEPTIONIST_PERMISSIONS)
    Role.objects.filter(name__iexact="HR").exclude(code="EUCL_HR").update(name="HR (old)")
    hr = system_role("EUCL_HR", "HR", "EUCL employee in HR: uses the services and manages EUCL employees", False, HR_PERMISSIONS)

    # The one-page roles become Receptionist
    for role in Role.objects.filter(code__in=PAGE_ROLES):
        for profile in UserProfile.objects.filter(roles=role):
            profile.roles.add(receptionist)
        role.delete()

    # Employees of the HR department get the HR role
    for employee in Employee.objects.all():
        if employee.department.strip().upper() == "HR":
            profile = UserProfile.objects.filter(user_id=employee.user_id).first()
            if profile is not None:
                profile.roles.add(hr)


